function esc(value){const el=document.createElement('span');el.textContent=value??'';return el.innerHTML}
function dateText(value){if(!value)return 'তারিখ নেই';const date=new Date(value);return Number.isNaN(date.getTime())?'তারিখ নেই':new Intl.DateTimeFormat('bn-BD',{day:'numeric',month:'short',year:'numeric'}).format(date)}
function dateTimeText(value){if(!value)return 'সময় নেই';const date=new Date(value);return Number.isNaN(date.getTime())?'সময় নেই':new Intl.DateTimeFormat('bn-BD',{dateStyle:'medium',timeStyle:'short'}).format(date)}
function toast(message){$('toast').textContent=message;$('toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('on'),2400)}
function arrayValue(value){return (Array.isArray(value)?value:[value]).map(item=>String(item||'').trim()).filter(Boolean)}
function appearance(){try{return {...defaultAppearance,...JSON.parse(localStorage.getItem('uuuTT.appearance')||'{}')}}catch(_error){return {...defaultAppearance}}}
function resolvedDesign(next=appearance()){
  if(previewDesignId&&designIds.includes(previewDesignId))return previewDesignId;
  const requested=next.preset;
  if(designSettings.allowUserOverride&&requested&&requested!=='admin'&&designIds.includes(requested))return requested;
  return designIds.includes(designSettings.defaultPreset)?designSettings.defaultPreset:'calm';
}
function applyAppearance(next=appearance()){
  const dark=next.mode==='dark'||(next.mode==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.body.classList.toggle('dark',dark);
  [...document.body.classList].filter(name=>/^(accent|tint|density|text|mobile|marker|design)-/.test(name)||name==='group-panel').forEach(name=>document.body.classList.remove(name));
  document.body.dataset.design='legacy';
  document.documentElement.dataset.theme=dark?'dark':'light';
  document.querySelectorAll('#themeButton,#bottomTheme').forEach(button=>button.setAttribute('aria-label',dark?'Light mode চালু করুন':'Dark mode চালু করুন'));
}
function saveAppearance(){const next={preset:$('themePreset').value,mode:$('themeMode').value,accent:$('themeAccent').value,tint:$('themeTint').value,density:$('themeDensity').value,size:$('themeSize').value,group:$('themeGroup').value,mobile:$('themeMobile').value,marker:$('themeMarker').value};localStorage.setItem('uuuTT.appearance',JSON.stringify(next));localStorage.setItem('uuuTT.theme',next.mode);applyAppearance(next)}
function configureThemePreset(){const select=$('themePreset'),allowed=designSettings.allowUserOverride;select.disabled=!allowed;select.closest('label').classList.toggle('is-disabled',!allowed);$('themePresetHint').textContent=allowed?`Admin default: ${designPresets.find(item=>item.id===designSettings.defaultPreset)?.name||'Calm Command'}`:'Admin ব্যক্তিগত design পরিবর্তন বন্ধ রেখেছেন।'}
function openTheme(){const value=appearance();configureThemePreset();$('themePreset').value=designSettings.allowUserOverride&&designIds.includes(value.preset)?value.preset:'admin';$('themeMode').value=value.mode;$('themeAccent').value=value.accent;$('themeTint').value=value.tint;$('themeDensity').value=value.density;$('themeSize').value=value.size;$('themeGroup').value=value.group;$('themeMobile').value=value.mobile;$('themeMarker').value=value.marker;if(!$('themeDialog').open)$('themeDialog').showModal()}
function closeTheme(){if($('themeDialog').open)$('themeDialog').close()}
function normalizeView(view,index=0){const condition=view?.condition||view?.cond||{};return {id:String(view?.id||`view_${index+1}`).toLowerCase().replace(/[^a-z0-9_-]+/g,'_'),name:String(view?.name||`Special ${index+1}`),color:/^#[0-9a-f]{6}$/i.test(view?.color||'')?view.color:'#7C3AED',active:view?.active!==false,tag:view?.tag!==false,condition}}
function taskMatchesView(task,view){const c=view?.condition||{};const checks=[];if(c.taskType||c.type)checks.push(arrayValue(c.taskType||c.type).includes(task.taskType));if(c.status)checks.push(arrayValue(c.status).includes(task.status));if(c.priority)checks.push(arrayValue(c.priority).includes(task.priority));if(c.platform)checks.push(arrayValue(c.platform).includes(task.platform));if(c.person){const people=arrayValue(c.person).map(x=>x.toLowerCase()),taskPeople=[task.issuedPerson,...(task.approvedBy||[])].map(x=>String(x||'').toLowerCase());checks.push(people.some(person=>taskPeople.some(value=>value.includes(person))))}return checks.length>0&&checks.every(Boolean)}
function renderSpecialTabs(){const active=specialViews.filter(view=>view.active);$('specialTabs').innerHTML=active.map(view=>`<button class="tab${state.specialId===view.id?' active':''}" type="button" data-special-id="${esc(view.id)}" style="--special-color:${esc(view.color)}">${esc(view.name)}</button>`).join('');if(state.specialId&&!active.some(view=>view.id===state.specialId)){state.specialId='';state.view='pending'}}

function renderSummary(s){
  $('pendingCount').textContent=s.pending;
  $('legacyPendingCount').textContent=s.pending;
  const metrics=[['Urgent',s.urgent,'#ef4444'],['Pending',s.waiting,'#eab308'],['Task Added',s.added,'#3b82f6'],['All Tasks',s.total,'#8b5cf6']];
  $('summaryGrid').innerHTML=metrics.map(m=>`<div class="metric"><strong>${m[1]}</strong><span><i style="background:${m[2]}"></i>${m[0]}</span></div>`).join('');
  $('legacySideStats').innerHTML=metrics.map(m=>`<button class="legacy-nav legacy-stat" type="button" data-summary-status="${esc(m[0])}"><i class="legacy-dot" style="background:${m[2]}"></i><span>${esc(m[0])}</span><strong>${m[1]}</strong></button>`).join('');
  $('progressFill').style.width=(s.total?Math.min(100,(s.pending/s.total)*100):0)+'%';
  $('statusFilter').innerHTML='<option value="">All Status</option>'+s.statuses.map(x=>`<option>${esc(x)}</option>`).join('');
}

function card(t,index){
  const view=`<button class="task-edit-button" type="button" data-detail-index="${index}">View</button>`;
  const edit=!t.isDeleted&&(permissions.edit||permissions.status)?`<button class="task-edit-button" type="button" data-edit-index="${index}">Edit</button>`:'';
  const adminAction=permissions.delete?(t.isDeleted?`<button class="restore-button" type="button" data-restore-index="${index}">Restore</button>`:`<button class="task-edit-button danger-button" type="button" data-delete-index="${index}">Delete</button>`):'';
  const viewTags=specialViews.filter(view=>view.active&&view.tag&&taskMatchesView(t,view)).map(view=>`<span class="chip special-chip" style="--chip-color:${esc(view.color)}">${esc(view.name)}</span>`).join('');
  return `<article class="task-card editable${highlightTaskId===t.id?' just-saved':''}" data-priority="${esc(t.priority)}" style="--priority:${priorityColors[t.priority]||'#9ca3af'};--status-color:${statusColors[t.isDeleted?'Deleted':t.status]||'#9ca3af'}">
    <div class="task-main"><div class="task-id-line"><strong>${esc(t.id)}</strong></div><h3>${esc(t.title||t.details)}</h3><p>${esc(t.details)}</p><div class="task-meta"><span class="chip">${esc(t.id)}</span><span class="chip">${esc(t.menuPath)}</span><span class="chip">${esc(t.platform)}</span>${viewTags}</div></div>
    <div class="desktop-task-field"><span class="priority-badge">${esc(t.priority||'—')}</span></div>
    <div class="desktop-task-field"><span class="status">${esc(t.isDeleted?'Deleted':t.status)}</span></div>
    <div class="desktop-task-field"><strong>${esc(t.platform||'—')}</strong><small>${esc(t.taskType||'')}</small></div>
    <div class="desktop-task-field"><strong>${esc(t.issuedPerson||t.issuedDepartment||'—')}</strong></div>
    <div class="desktop-task-field"><strong>${esc(t.entryBy||'—')}</strong></div>
    <div class="task-side"><time datetime="${esc(t.createdAt)}">${dateText(t.createdAt)}</time><span class="mobile-task-badge status">${esc(t.isDeleted?'Deleted':t.status)}</span><span class="mobile-task-badge chip">${esc(t.priority)}</span><div class="task-card-actions">${view}${edit}${adminAction}</div></div>
  </article>`;
}

function renderList(){
  if(!state.items.length)$('taskList').innerHTML='<div class="empty">এই বাছাইয়ে কোনো task পাওয়া যায়নি।</div>';
  else if(!state.group)$('taskList').innerHTML=state.items.map(card).join('');
  else{
    const grouped=new Map();state.items.forEach((task,index)=>{const key=String(task[state.group]||'Unspecified');if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push({task,index})});
    $('taskList').innerHTML=[...grouped.entries()].map(([name,items])=>`<section class="task-group${collapsedGroups.has(name)?' collapsed':''}" data-group-name="${esc(name)}"><button class="task-group-head" type="button" aria-expanded="${collapsedGroups.has(name)?'false':'true'}"><span>${collapsedGroups.has(name)?'▸':'▾'} ${esc(name)}</span><i>${items.length.toLocaleString('bn-BD')}টি</i></button><div class="task-group-body">${items.map(item=>card(item.task,item.index)).join('')}</div></section>`).join('');
  }
  $('resultCount').textContent=state.total.toLocaleString('bn-BD')+'টি';$('loadMoreButton').hidden=!state.hasMore;
  $('dateRangeCount').textContent=state.total.toLocaleString('bn-BD')+'টি task';
  const active=document.querySelector('.tab.active');$('listTitle').textContent=state.search&&searchReturnView?'Search Results':(active?active.textContent:'Tasks');
}

async function load(reset=true){
  if(!repo)return;if(reset){state.offset=0;state.items=[];$('taskList').innerHTML='<div class="empty">লোড হচ্ছে…</div>'}
  try{const specialView=specialViews.find(view=>view.id===state.specialId);if(state.group&&reset){const rows=[];let offset=0,total=0;do{const page=await repo.listTasks({...state,specialView,offset,limit:1000});rows.push(...page.items);offset=rows.length;total=page.total}while(offset<total);state.items=rows;state.total=total;state.hasMore=false;state.offset=rows.length}else{const result=await repo.listTasks({...state,specialView,limit:config.pageSize});state.items=reset?result.items:state.items.concat(result.items);state.total=result.total;state.hasMore=result.hasMore;state.offset=state.items.length}renderList()}
  catch(error){$('taskList').innerHTML=`<div class="empty">${esc(error.message)}</div>`;toast('Data load করা যায়নি')}
}

