  $('departmentOptions').innerHTML=(formOptions.department||[]).map(value=>`<option value="${esc(value)}"></option>`).join('');$('personOptions').innerHTML=(formOptions.person||[]).map(value=>`<option value="${esc(value)}"></option>`).join('');
