  $('taskApprovedOptions').innerHTML=people.length?people.map(name=>`<label class="approved-option"><input type="checkbox" data-approved-name="${esc(name)}"${selected.has(name)?' checked':''}${$('taskApprovedSearch').disabled?' disabled':''}><span>${esc(name)}</span></label>`).join(''):'<div class="empty">কোনো নাম পাওয়া যায়নি।</div>';
