function closeTaskEditor(){if($('taskEditorDialog').open)$('taskEditorDialog').close()}
function cancelTaskEditor(){const task=detailReturnTask;detailReturnTask=null;closeTaskEditor();if(task)openTaskDetail(task)}
function openTaskEditor(task=null,returnTask=null){
  editingTask=task;detailReturnTask=returnTask;
  const editing=Boolean(task);$('taskForm').reset();$('taskFormError').textContent='';$('taskEditorMode').textContent=editing?task.id:'New task';$('taskEditorTitle').textContent=editing?'Task সম্পাদনা করুন':'Task তৈরি করুন';$('taskSaveButton').textContent=editing?'Update Task':'Save Task';
  $('taskDbId').value=task?.dbId||'';$('taskRevision').value=task?.revision??'';$('taskOriginalStatus').value=task?.status||'';
  setOptions('taskPriority',formOptions.priority,task?.priority||formOptions.priority?.[0]);setOptions('taskStatus',formOptions.status,task?.status||formOptions.status?.[0]);setOptions('taskType',formOptions.taskType,task?.taskType||formOptions.taskType?.[0]);setOptions('taskPlatform',formOptions.platform,task?.platform||formOptions.platform?.[0]);
  setOptionalOptions('taskActionStatus',formOptions.actionStatus,task?.actionStatus||'');setOptionalOptions('taskProgress',formOptions.progress,task?.progress||'');setOptionalOptions('taskModule',formOptions.module,task?.module||'');
  $('taskMenu').value=task?.menuPath||'';$('taskTitle').value=task?.title||'';$('taskDetails').value=task?.details||'';$('taskDepartment').value=task?.issuedDepartment||'';$('taskPerson').value=task?.issuedPerson||'';$('taskApprovedBy').value=(task?.approvedBy||[]).join(', ');$('taskApprovedSearch').value='';$('taskNumber').value=task?.taskNo||'';$('taskRegPin').value=task?.regPin||'';$('taskAppVersion').value=task?.appVersion||'';$('taskLinks').value=(task?.links||[]).map(link=>typeof link==='string'?link:(link?.url||link?.link||'')).filter(Boolean).join('\n');$('taskSolution').value=task?.solution||'';$('taskRemarks').value=task?.remarks||'';
  const canEdit=!editing||permissions.edit;for(const id of ['taskPriority','taskType','taskPlatform','taskMenu','taskTitle','taskDetails','taskDepartment','taskPerson','taskApprovedBy','taskNumber','taskRegPin','taskActionStatus','taskProgress','taskModule','taskAppVersion','taskLinks','taskSolution','taskRemarks'])$(id).disabled=!canEdit;$('taskApprovedSearch').disabled=!canEdit;renderApprovedOptions();$('taskStatus').disabled=editing&&!permissions.status;$('taskSaveButton').hidden=editing&&!permissions.edit&&!permissions.status;
  if(!$('taskEditorDialog').open)$('taskEditorDialog').showModal();setTimeout(()=>(editing?$('taskTitle'):$('taskPriority')).focus(),40);
}
function formPayload(){return {priority:$('taskPriority').value,status:$('taskStatus').value,task_type:$('taskType').value,platform:$('taskPlatform').value,menu_path:$('taskMenu').value.trim(),title:$('taskTitle').value.trim(),details:$('taskDetails').value.trim(),issued_department:$('taskDepartment').value.trim(),issued_person:$('taskPerson').value.trim(),approved_by:$('taskApprovedBy').value.split(',').map(value=>value.trim()).filter(Boolean),task_no:$('taskNumber').value.trim(),reg_pin:$('taskRegPin').value.trim(),action_status:$('taskActionStatus').value,progress:$('taskProgress').value,module:$('taskModule').value,app_version:$('taskAppVersion').value.trim(),links:$('taskLinks').value.split(/\r?\n/).map(value=>value.trim()).filter(Boolean),solution:$('taskSolution').value.trim(),remarks:$('taskRemarks').value.trim()}}
function taskPatch(task){return {priority:task?.priority||'',task_type:task?.taskType||'',platform:task?.platform||'',menu_path:task?.menuPath||'',title:task?.title||'',details:task?.details||'',issued_department:task?.issuedDepartment||'',issued_person:task?.issuedPerson||'',approved_by:task?.approvedBy||[],task_no:task?.taskNo||'',reg_pin:task?.regPin||'',action_status:task?.actionStatus||'',progress:task?.progress||'',module:task?.module||'',app_version:task?.appVersion||'',links:(task?.links||[]).map(link=>typeof link==='string'?link:(link?.url||link?.link||'')).filter(Boolean),solution:task?.solution||'',remarks:task?.remarks||''}}
function comparable(value){return Array.isArray(value)?value.map(item=>String(item??'').trim()):String(value??'').trim()}
function changedPayload(next,current){return Object.fromEntries(Object.entries(next).filter(([key,value])=>JSON.stringify(comparable(value))!==JSON.stringify(comparable(current[key]))))}
function closeTaskDetail(){if($('taskDetailDialog').open)$('taskDetailDialog').close()}
function detailItem(label,value){return `<div class="detail-item"><span>${esc(label)}</span><strong>${esc(value||'—')}</strong></div>`}
function safeUrl(value){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:''}catch(_error){return ''}}
async function openTaskDetail(task){
  $('taskDetailDialog').dataset.index=String(state.items.indexOf(task));$('taskDetailId').textContent=`${task.id} • Revision ${task.revision}`;$('taskDetailTitle').textContent=task.title||task.details;
  const links=(task.links||[]).map(item=>typeof item==='string'?item:(item?.url||item?.link||'')).map(safeUrl).filter(Boolean);
  const discussions=(task.discussions||[]).map(item=>typeof item==='string'?item:[item?.name||item?.person||item?.with,item?.message||item?.text,item?.date||item?.at].filter(Boolean).join(' • ')).filter(Boolean);
  $('taskDetailBody').innerHTML=`<p class="detail-copy">${esc(task.details)}</p><div class="detail-grid">${detailItem('Priority',task.priority)}${detailItem('Status',task.status)}${detailItem('Task Type',task.taskType)}${detailItem('Platform',task.platform)}${detailItem('Menu',task.menuPath)}${detailItem('Task No.',task.taskNo)}${detailItem('Reg / Pin',task.regPin)}${detailItem('Action Status',task.actionStatus)}${detailItem('Progress',task.progress)}${detailItem('Module',task.module)}${detailItem('Version',task.appVersion)}${detailItem('Issued By',[task.issuedDepartment,task.issuedPerson].filter(Boolean).join(' • '))}${detailItem('Approved By',(task.approvedBy||[]).join(', '))}${detailItem('Created By',task.createdByName)}${detailItem('Updated By',task.updatedByName)}${detailItem('Created',dateTimeText(task.createdAt))}${detailItem('Updated',dateTimeText(task.updatedAt))}</div>${task.solution?`<h3>Solution</h3><p class="detail-copy">${esc(task.solution)}</p>`:''}${task.remarks?`<h3>Remarks</h3><p class="detail-copy">${esc(task.remarks)}</p>`:''}${discussions.length?`<h3>Discussed With</h3>${discussions.map(item=>`<p class="detail-copy">${esc(item)}</p>`).join('')}`:''}${links.length?`<div class="detail-links"><strong>Links</strong>${links.map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a>`).join('')}</div>`:''}`;
  $('taskDetailEdit').hidden=task.isDeleted||(!permissions.edit&&!permissions.status);$('taskHistoryList').innerHTML='<div class="empty">History লোড হচ্ছে…</div>';if(!$('taskDetailDialog').open)$('taskDetailDialog').showModal();
  try{const logs=await repo.getTaskLogs(task.dbId);$('taskHistoryList').innerHTML=logs.length?logs.map(log=>`<div class="history-item"><strong>${esc(log.action.replaceAll('_',' '))}</strong><p>${esc(log.message||'')} • ${esc(log.actor_name||'System')} • ${esc(dateTimeText(log.created_at||log.recorded_at))}</p></div>`).join(''):'<div class="empty">কোনো history পাওয়া যায়নি।</div>'}catch(error){$('taskHistoryList').innerHTML=`<div class="empty">${esc(error.message)}</div>`}
}
async function saveTask(event){
  event.preventDefault();const button=$('taskSaveButton'),payload=formPayload();if(!payload.details){$('taskFormError').textContent='Details লিখুন।';return}button.disabled=true;$('taskFormError').textContent='';
  try{
    const dbId=$('taskDbId').value;let savedId='';if(!dbId){const created=await repo.createTask(payload);savedId=created.id;toast(`${created.id} তৈরি হয়েছে`)}else{let revision=Number($('taskRevision').value),changed;const {status,...patch}=payload,contentChanges=changedPayload(patch,taskPatch(editingTask));if(permissions.edit&&Object.keys(contentChanges).length){changed=await repo.updateTask(dbId,revision,contentChanges);revision=changed.revision}if(status!==$('taskOriginalStatus').value){if(!permissions.status)throw new Error('Status পরিবর্তনের permission নেই।');changed=await repo.setTaskStatus(dbId,revision,status)}savedId=changed?.id||editingTask?.id||'';toast(changed?`${changed.id} আপডেট হয়েছে`:'কোনো পরিবর্তন নেই')}
    detailReturnTask=null;highlightTaskId=savedId;closeTaskEditor();renderSummary(await repo.getSummary());await load(true);if(savedId)setTimeout(()=>{if(highlightTaskId===savedId){highlightTaskId='';document.querySelectorAll('.task-card.just-saved').forEach(card=>card.classList.remove('just-saved'))}},1900);
  }catch(error){$('taskFormError').textContent=error.message?.includes('changed by another user')?'Taskটি অন্য জায়গা থেকে পরিবর্তিত হয়েছে। তালিকা refresh করে আবার চেষ্টা করুন।':(error.message||'Task save করা যায়নি।')}
  finally{button.disabled=false}
}
function closeDeleteConfirm(){if($('deleteConfirmDialog').open)$('deleteConfirmDialog').close();pendingDeleteTask=null}
function openDeleteConfirm(task){pendingDeleteTask=task;$('deleteConfirmText').textContent=`${task.id} — ${task.title||task.details} Deleted তালিকায় যাবে এবং পরে Restore করা যাবে।`;if(!$('deleteConfirmDialog').open)$('deleteConfirmDialog').showModal()}
async function confirmDelete(){if(!pendingDeleteTask)return;const task=pendingDeleteTask,button=$('deleteConfirmButton');button.disabled=true;try{await repo.softDeleteTask(task.dbId,task.revision);closeDeleteConfirm();toast(`${task.id} Deleted হয়েছে`);renderSummary(await repo.getSummary());await load(true)}catch(error){toast(error.message||'Task delete করা যায়নি')}finally{button.disabled=false}}
async function restoreDeletedTask(task){try{await repo.restoreTask(task.dbId,task.revision);toast(`${task.id} Restore হয়েছে`);renderSummary(await repo.getSummary());await load(true)}catch(error){toast(error.message||'Task restore করা যায়নি')}}
function adminItemName(item){return typeof item==='string'?item:(item?.name||'')}
function setAdminMessage(message,error=false){$('adminMessage').textContent=message;$('adminMessage').classList.toggle('error',error)}
function renderAdminUsers(){
  $('adminUserList').innerHTML=adminUsers.length?adminUsers.map((user,index)=>`<div class="admin-user-row"><div class="admin-user-identity"><strong>${esc(user.display_name||user.email.split('@')[0])}</strong><span>${esc(user.email)}</span></div><select aria-label="${esc(user.email)} role" data-admin-role="${index}">${['Admin','Editor','Viewer'].map(role=>`<option${role===user.role?' selected':''}>${role}</option>`).join('')}</select><label class="admin-active"><input type="checkbox" data-admin-active="${index}"${user.is_active?' checked':''}> Active</label><button class="admin-save-user" type="button" data-admin-save="${index}">Save</button></div>`).join(''):'<div class="empty">কোনো approved user নেই।</div>';
}
function renderAdminList(){const name=$('adminListName').value,items=adminLists[name]||[];$('adminListItems').value=items.map(item=>`${typeof item==='object'&&item?.active===false?'!':''}${adminItemName(item)}`).filter(Boolean).join('\n')}
function renderAdminAudit(logs){$('adminAuditList').innerHTML=logs.length?logs.map(log=>`<div class="admin-audit-item"><strong>${esc(log.action.replaceAll('_',' '))} • ${esc(log.target)}</strong><p>${esc(log.actor_email||'System')} • ${esc(dateTimeText(log.created_at))}</p></div>`).join(''):'<div class="empty">কোনো admin activity নেই।</div>'}
function viewRule(view){const condition=view.condition||{},keys=['taskType','type','person','status','priority','platform'],key=keys.find(name=>arrayValue(condition[name]).length)||keys.find(name=>condition[name]!==undefined)||'taskType';return {field:key==='type'?'taskType':key,values:arrayValue(condition[key]).join(', ')}}
function renderAdminViews(){
  $('adminViewList').innerHTML=adminSpecialViews.length?adminSpecialViews.map((view,index)=>{const rule=viewRule(view);return `<div class="admin-view-row"><label><span>Name</span><input data-view-name="${index}" value="${esc(view.name)}"></label><label><span>Color</span><input type="color" data-view-color="${index}" value="${esc(view.color)}"></label><label><span>Rule</span><select data-view-field="${index}">${[['taskType','Task Type'],['person','Person'],['status','Status'],['priority','Priority'],['platform','Platform']].map(([value,label])=>`<option value="${value}"${rule.field===value?' selected':''}>${label}</option>`).join('')}</select></label><label><span>Values (comma separated)</span><input data-view-values="${index}" value="${esc(rule.values)}"></label><div class="admin-view-flags"><label><input type="checkbox" data-view-active="${index}"${view.active?' checked':''}> Show</label><label><input type="checkbox" data-view-tag="${index}"${view.tag?' checked':''}> Tag</label></div><button class="admin-view-remove" type="button" data-view-remove="${index}">Remove</button></div>`}).join(''):'<div class="empty">কোনো special tab নেই। Add চাপুন।</div>';
}
function renderAdminDesigns(){
  $('adminDesignList').innerHTML=designPresets.map(item=>`<article class="design-preset-card${designSettings.defaultPreset===item.id?' selected':''}" data-design-card="${item.id}"><label><input type="radio" name="adminDesignPreset" value="${item.id}"${designSettings.defaultPreset===item.id?' checked':''}><span class="design-preset-number">${item.number}</span><strong>${esc(item.name)}</strong></label><p>${esc(item.description)}</p><div class="design-preset-swatches" aria-hidden="true"><i></i><i></i><i></i></div><button class="cancel-button compact" type="button" data-design-preview="${item.id}">Preview</button></article>`).join('');
  $('adminDesignOverride').checked=designSettings.allowUserOverride;
}
async function loadAdminUsers(){adminUsers=await repo.getAdminUsers();renderAdminUsers()}
