async function loadAdminViews(){adminSpecialViews=(await repo.getSpecialViews()).map(normalizeView);renderAdminViews()}
async function loadDesignSettings(){designSettings={defaultPreset:'calm',allowUserOverride:true,...await repo.getDesignSettings()};if(!designIds.includes(designSettings.defaultPreset))designSettings.defaultPreset='calm';configureThemePreset();applyAppearance();renderAdminDesigns()}
async function openAdmin(){if(!permissions.settings)return;setAdminMessage('');if(!$('adminDialog').open)$('adminDialog').showModal();try{await Promise.all([loadAdminUsers(),loadAdminLists(),loadAdminViews(),loadAdminAudit(),loadDesignSettings()])}catch(error){setAdminMessage(error.message||'Admin data load করা যায়নি',true)}}
