function closeAdmin(){stopDesignPreview();if($('adminDialog').open)$('adminDialog').close()}
function showAdminSection(name){document.querySelectorAll('.admin-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.adminSection===name));$('adminUsersSection').hidden=name!=='users';$('adminListsSection').hidden=name!=='lists';$('adminViewsSection').hidden=name!=='views';$('adminDesignsSection').hidden=name!=='designs';$('adminAuditSection').hidden=name!=='audit'}
function previewAdminDesign(id){if(!designIds.includes(id))return;previewDesignId=id;applyAppearance();document.querySelectorAll('.design-preset-card').forEach(card=>card.classList.toggle('previewing',card.dataset.designCard===id));setAdminMessage(`${designPresets.find(item=>item.id===id).name} preview চলছে—Save না করলে পরিবর্তন স্থায়ী হবে না।`)}
async function saveAdminDesign(){const selected=document.querySelector('input[name="adminDesignPreset"]:checked')?.value,allowUserOverride=$('adminDesignOverride').checked,button=$('adminDesignSave');if(!designIds.includes(selected)){setAdminMessage('একটি design নির্বাচন করুন।',true);return}button.disabled=true;setAdminMessage('Design save হচ্ছে…');try{const saved=await repo.updateAdminDesign(selected,allowUserOverride);designSettings={defaultPreset:saved?.defaultPreset||selected,allowUserOverride:saved?.allowUserOverride??allowUserOverride};previewDesignId=null;renderAdminDesigns();configureThemePreset();applyAppearance();setAdminMessage(`${designPresets.find(item=>item.id===selected).name} এখন default design।`);await loadAdminAudit()}catch(error){setAdminMessage(error.message||'Design update করা যায়নি',true)}finally{button.disabled=false}}
async function saveAdminUser(index){const user=adminUsers[index],button=document.querySelector(`[data-admin-save="${index}"]`),role=document.querySelector(`[data-admin-role="${index}"]`).value,isActive=document.querySelector(`[data-admin-active="${index}"]`).checked;button.disabled=true;setAdminMessage('Save হচ্ছে…');try{await repo.updateAdminUser(user.email,role,isActive);setAdminMessage(`${user.email} আপডেট হয়েছে`);await Promise.all([loadAdminUsers(),loadAdminAudit()])}catch(error){setAdminMessage(error.message||'User update করা যায়নি',true)}finally{button.disabled=false}}
async function saveAdminList(){const listName=$('adminListName').value,lines=$('adminListItems').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean),existing=adminLists[listName]||[],items=lines.map(line=>{const inactive=line.startsWith('!'),name=(inactive?line.slice(1):line).trim(),old=existing.find(item=>adminItemName(item).toLowerCase()===name.toLowerCase());if(typeof old==='object')return {...old,name,active:!inactive};return inactive?{name,active:false}:name}),button=$('adminListSave');button.disabled=true;setAdminMessage('Save হচ্ছে…');try{await repo.updateAdminList(listName,items);setAdminMessage(`${listName} list আপডেট হয়েছে`);await Promise.all([loadAdminLists(),loadAdminAudit()]);formOptions=await repo.getOptions();configureWriteUi();renderSummary(await repo.getSummary())}catch(error){setAdminMessage(error.message||'List update করা যায়নি',true)}finally{button.disabled=false}}
function addAdminView(){adminSpecialViews.push(normalizeView({id:`view_${Date.now()}`,name:'New Tab',color:'#7C3AED',active:true,tag:true,condition:{taskType:['Our Task']}},adminSpecialViews.length));renderAdminViews()}
